theme.customCss:
.laser-pointer-item {
position: relative;
list-style: disc;
}

.laser-pointer-item::marker {
color: transparent;
}

.laser-pointer-dot {
position: absolute;
left: -0.88rem;
top: 0.72em;
width: 0.34rem;
height: 0.34rem;
border-radius: 50%;
background-color: #ff2a2a;
box-shadow: 0 0 0.35rem rgba(255, 0, 0, 0.85);
animation: jitter-dot 0.3s infinite;
}

@keyframes jitter-dot {
0% {
transform: translate(0, -50%);
}

25% {
transform: translate(1px, calc(-50% - 1px));
}

50% {
transform: translate(-1px, calc(-50% + 1px));
}

75% {
transform: translate(1px, calc(-50% + 1px));
}

100% {
transform: translate(-1px, calc(-50% - 1px));
}
}

